python.solution:
from collections import defaultdict

def rollup(edges, premiums, root):
    children = defaultdict(list)
    for parent, child in edges:
        children[parent].append(child)

    totals = {}

    def dfs(node):
        total = premiums.get(node, 0)
        for c in children[node]:
            total += dfs(c)
        totals[node] = total
        return total

    dfs(root)
    return totals

